package szserver.world;

import szserver.client.CompleteTileState;
import szserver.client.NativeResidentChunkCodec;
import java.io.*;
import java.util.*;

/** Lossless map-operation payloads. All binary encoding/decoding belongs to workers. */
public final class ResidentMapEvents {
    private static final int BLOCK=0x535a4245,SCENE=0x535a5345,VERSION=1;
    private ResidentMapEvents(){}
    public record Blocks(long sequence,List<ResidentBlockOperations.Delta> changes,Map<ResidentChunks.Key,Long> revisions){public Blocks{changes=List.copyOf(changes);revisions=Map.copyOf(revisions);}}
    public record Scene(Map<ResidentChunks.Key,Long> revisions,List<byte[]> chunks,byte[] metadata){public Scene{revisions=Map.copyOf(revisions);chunks=chunks.stream().map(byte[]::clone).toList();metadata=metadata.clone();}public Scene(Map<ResidentChunks.Key,Long> revisions,List<byte[]> chunks){this(revisions,chunks,new byte[0]);}@Override public List<byte[]> chunks(){return chunks.stream().map(byte[]::clone).toList();}@Override public byte[] metadata(){return metadata.clone();}}
    public record ObjectChanges(Map<UUID,ScenePayload.Entry> before,Map<UUID,ScenePayload.Entry> after){public ObjectChanges{before=Collections.unmodifiableMap(new LinkedHashMap<>(before));after=Collections.unmodifiableMap(new LinkedHashMap<>(after));}}
    private static void revisions(DataOutputStream out,Map<ResidentChunks.Key,Long> values)throws IOException{out.writeInt(values.size());for(var key:values.keySet().stream().sorted(Comparator.comparingInt(ResidentChunks.Key::x).thenComparingInt(ResidentChunks.Key::z)).toList()){out.writeInt(key.x());out.writeInt(key.z());out.writeLong(values.get(key));}}
    private static Map<ResidentChunks.Key,Long> revisions(DataInputStream in)throws IOException{int count=in.readInt();if(count<1||count>SceneLimits.PLACEMENTS)throw new IOException("resident_event_chunk_count");Map<ResidentChunks.Key,Long> result=new LinkedHashMap<>();for(int i=0;i<count;i++){var key=new ResidentChunks.Key(in.readInt(),in.readInt());long value=in.readLong();if(Math.abs((long)key.x())>MapBounds.CHUNK||Math.abs((long)key.z())>MapBounds.CHUNK||value<1||result.put(key,value)!=null)throw new IOException("resident_event_chunk_revision");}return Map.copyOf(result);}
    private static void tile(DataOutputStream out,TilePayload.Tile tile)throws IOException{out.writeInt(tile==null?0:tile.recordSize());if(tile==null)return;out.write(tile.record());out.writeInt(tile.completeStateSize());if(tile.completeStateSize()>0)out.write(tile.completeState());}
    private static TilePayload.Tile tile(DataInputStream in)throws IOException{int size=in.readInt();if(size==0)return null;if(size<20||size>68||size>in.available())throw new IOException("resident_event_tile_record");TilePayload.Tile tile=TilePayload.single(in.readNBytes(size));int full=in.readInt();if(full<0||full>CompleteTileState.MAX_STATE||full>in.available())throw new IOException("resident_event_tile_state");if(full>0){var complete=CompleteTileState.decode(in.readNBytes(full));if(!Arrays.equals(complete.record(),tile.record()))throw new IOException("resident_event_tile_appearance");tile=complete;}return tile;}
    public static ResidentOperationLog.Payload blocks(ResidentBlockOperations.Change change){
        long bound=128+change.revisions().size()*32L;for(var delta:change.changes()){bound+=64;for(var tile:new TilePayload.Tile[]{delta.expectedTile(),delta.tile()})if(tile!=null)bound+=tile.recordSize()+tile.completeStateSize()+16;}
        return new ResidentOperationLog.Payload(bound,()->{var bytes=new ByteArrayOutputStream();try(var out=new DataOutputStream(bytes)){out.writeInt(BLOCK);out.writeInt(VERSION);out.writeLong(change.sequence());revisions(out,change.revisions());out.writeInt(change.changes().size());for(var delta:change.changes()){var p=delta.position();out.writeInt(p.x());out.writeInt(p.y());out.writeInt(p.z());out.writeInt(delta.expectedPacked());out.writeInt(delta.packed());tile(out,delta.expectedTile());tile(out,delta.tile());}}return bytes.toByteArray();});
    }
    public static Blocks blocks(ResidentOperationLog.Stored event)throws IOException{
        event=ResidentCommandEnvelope.nativeEvent(event);
        if(!event.kind().equals("block"))throw new IOException("resident_event_kind");try(var in=new DataInputStream(new ByteArrayInputStream(event.payload()))){if(in.readInt()!=BLOCK||in.readInt()!=VERSION)throw new IOException("resident_event_block_version");long sequence=in.readLong();var revisions=revisions(in);int count=in.readInt();if(sequence<1||count<1||count>32)throw new IOException("resident_event_block_count");List<ResidentBlockOperations.Delta> changes=new ArrayList<>(count);Set<World.Block> unique=new HashSet<>();for(int i=0;i<count;i++){var p=new World.Block(in.readInt(),in.readInt(),in.readInt());int before=in.readInt(),after=in.readInt();if(Math.abs((long)p.x())>MapBounds.HORIZONTAL||Math.abs((long)p.z())>MapBounds.HORIZONTAL||p.y()<0||p.y()>255||!unique.add(p))throw new IOException("resident_event_block_position");changes.add(new ResidentBlockOperations.Delta(p,before,after,tile(in),tile(in)));}if(in.available()!=0)throw new IOException("resident_event_block_trailing");return new Blocks(sequence,changes,revisions);}catch(IllegalArgumentException invalid){throw new IOException("resident_event_block_data",invalid);}
    }
    public static ResidentOperationLog.Payload scenes(Map<ResidentChunks.Key,NativeResidentChunkCodec.PreparedScenes> prepared,Map<ResidentChunks.Key,Long> revisions){
        var frozenRevisions=Map.copyOf(revisions);List<ResidentOperationLog.Payload> parts=prepared.entrySet().stream().sorted(Comparator.comparingInt((Map.Entry<ResidentChunks.Key,NativeResidentChunkCodec.PreparedScenes> entry)->entry.getKey().x()).thenComparingInt(entry->entry.getKey().z())).map(entry->entry.getValue().history()).toList();long bound=128+frozenRevisions.size()*32L;for(var part:parts)bound+=4+part.bytes();return new ResidentOperationLog.Payload(bound,()->{var bytes=new ByteArrayOutputStream();try(var out=new DataOutputStream(bytes)){out.writeInt(SCENE);out.writeInt(VERSION);revisions(out,frozenRevisions);out.writeInt(parts.size());for(var part:parts){byte[] chunk=part.encoder().encode();out.writeInt(chunk.length);out.write(chunk);}}return bytes.toByteArray();});
    }
    public static Scene scenes(ResidentOperationLog.Stored event)throws IOException{
        event=ResidentCommandEnvelope.nativeEvent(event);
        if(!event.kind().equals("scene"))throw new IOException("resident_event_kind");try(var in=new DataInputStream(new ByteArrayInputStream(event.payload()))){if(in.readInt()!=SCENE)throw new IOException("resident_event_scene_version");int version=in.readInt();if(version!=VERSION&&version!=2)throw new IOException("resident_event_scene_version");var revisions=revisions(in);int count=in.readInt();if(count!=revisions.size())throw new IOException("resident_event_scene_count");List<byte[]> chunks=new ArrayList<>(count);for(int i=0;i<count;i++){int size=in.readInt();if(size<12||size>48*1024*1024||size>in.available())throw new IOException("resident_event_scene_size");chunks.add(in.readNBytes(size));}byte[] metadata=new byte[0];if(version==2){int size=in.readInt();if(size<20||size>48*1024*1024||size>in.available())throw new IOException("resident_event_metadata_size");metadata=in.readNBytes(size);}if(in.available()!=0)throw new IOException("resident_event_scene_trailing");return new Scene(revisions,chunks,metadata);}
    }
    public static ResidentOperationLog.Payload scenes(Map<ResidentChunks.Key,NativeResidentChunkCodec.PreparedScenes> prepared,Map<ResidentChunks.Key,Long> revisions,ResidentMetadataChanges metadata){
        var frames=scenes(prepared,revisions);if(metadata==null)return frames;return new ResidentOperationLog.Payload(frames.bytes()+4+metadata.bytes(),()->{byte[] base=frames.encoder().encode(),delta=metadata.encode();java.nio.ByteBuffer.wrap(base).putInt(4,2);var buffer=new ByteArrayOutputStream();try(var out=new DataOutputStream(buffer)){out.write(base);out.writeInt(delta.length);out.write(delta);}return buffer.toByteArray();});
    }
    private static ScenePayload.Entry objects(DataInputStream in,UUID identity,SceneRegistry.Manifest registry)throws IOException{
        int count=in.readInt();if(count<0||count>ScenePayload.MAX_OBJECTS)throw new IOException("resident_event_scene_occurrences");if(count==0)return null;List<ScenePayload.Occurrence> frames=new ArrayList<>(count);
        for(int i=0;i<count;i++){boolean container=in.readBoolean();String asset=in.readUTF();int size=in.readInt();if(asset.length()>1024||size<2||size>ScenePayload.MAX_OBJECT||size>in.available())throw new IOException("resident_event_scene_frame");byte[] frame=in.readNBytes(size);int oldId=java.nio.ByteBuffer.wrap(frame).getShort();SceneRegistry.Definition definition=asset.isEmpty()?registry.ids().get(oldId):registry.names().get(asset);if(definition==null)throw new IOException("resident_event_scene_asset_missing");java.nio.ByteBuffer.wrap(frame).putShort(0,(short)definition.id());SceneObject object=new SceneObject(definition.name(),frame);if(!object.identity().equals(identity))throw new IOException("resident_event_scene_identity");frames.add(new ScenePayload.Occurrence(container,object));}return ScenePayload.Entry.of(frames);
    }
    /** Stable asset names permit ID remapping; old nameless frames require the saved source registry. */
    public static Map<ResidentChunks.Key,ObjectChanges> objects(Scene scene,SceneRegistry.Manifest registry)throws IOException{
        java.util.Objects.requireNonNull(registry);Map<ResidentChunks.Key,ObjectChanges> result=new LinkedHashMap<>();for(byte[] raw:scene.chunks())try(var in=new DataInputStream(new ByteArrayInputStream(raw))){var key=new ResidentChunks.Key(in.readInt(),in.readInt());int count=in.readInt();if(!scene.revisions().containsKey(key)||count<0||count>ScenePayload.MAX_OBJECTS||result.containsKey(key))throw new IOException("resident_event_scene_chunk");Map<UUID,ScenePayload.Entry> before=new LinkedHashMap<>(),after=new LinkedHashMap<>();for(int i=0;i<count;i++){UUID id=new UUID(in.readLong(),in.readLong());if(before.containsKey(id))throw new IOException("resident_event_scene_duplicate");before.put(id,objects(in,id,registry));after.put(id,objects(in,id,registry));}if(in.available()!=0)throw new IOException("resident_event_scene_chunk_trailing");result.put(key,new ObjectChanges(before,after));}catch(IllegalArgumentException invalid){throw new IOException("resident_event_scene_data",invalid);}return Map.copyOf(result);
    }
}
